script:
special_project = {
	key = "RECOVER_DISABLED_NOMAD_VESSEL"
	days_to_research = 90
	timelimit = 1800
	tech_department = engineering_technology
	picture = GFX_evt_arkship_crisis
	icon = "gfx/interface/icons/situation_log/situation_log_quest.dds"
	location = yes

	event_scope = ship_event

	# Desc trigger scope is the disabled vessel (ship scope), so test the ship, not the fleet.
	desc = {
		trigger = { is_arkship_ship = yes }
		text = RECOVER_DISABLED_NOMAD_VESSEL_ARKSHIP_DESC
	}
	desc = {
		trigger = { is_arkship_ship = no }
		text = RECOVER_DISABLED_NOMAD_VESSEL_WAYSTATION_DESC
	}

	triggered_requirement = {
		text = CONSTRUCTOR_PROJECT_REQUIREMENTS
		count = 1
		trigger = {
			OR = {
				is_ship_class = shipclass_constructor	# Nomad Logistic Ships
				is_arkship_fleet = yes
			}
		}
	}

	on_success = {
		controller = {
			country_event = {
				id = arkship.1026
				scopes = {
					from = root.from		# the disabled fleet (location)
				}
			}
		}
	}

	# Auto-cancel when the target fleet is gone or no longer holds a disabled nomad ship
	# (covers destroyed, war-end re-enable via nomads.94, or re-enabled by other means).
	# Scopes here follow on_fail: FROMFROM = location (the disabled fleet).
	abort_trigger = {
		OR = {
			NOT = { exists = fromfrom }
			fromfrom = {
				NOR = {
					any_owned_ship = { is_arkship_ship = yes is_disabled = yes }
					any_owned_ship = { is_waystation_ship = yes is_disabled = yes }
				}
			}
		}
	}

	# Clear the guard flag so the fleet can be offered a fresh recovery project later.
	on_cancel = {
		if = {
			limit = { exists = fromfrom }
			fromfrom = { remove_fleet_flag = nomad_recovery_project_active }
		}
	}
}

special_project = {
	key = "CHAMPIONS_FORGE_TRAVEL"
	event_chain = "champions_forge_tournament_chain"
	days_to_research = 10
	timelimit = 270
	picture = GFX_evt_gladiators
	icon = "gfx/interface/icons/situation_log/situation_log_quest.dds"
	location = yes
	remove_when_completed = yes

	event_scope = ship_event

	requirements = {
		shipclass_military = 1
	}

	triggered_requirement = {
    	text = CHAMPIONS_FORGE_TRAVEL_FLEET_REQ
   		trigger = {
			OR = {
				AND = {
					event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_heavy_late }
					fleet_size <= 500
				}
				AND = {
					event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_medium_late }
					fleet_size <= 200
				}
				AND = {
					event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_medium_mid }
					fleet_size <= 100
				}
				AND = {
					event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_small_mid }
					fleet_size <= 50
				}
				AND = {
					event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_small_early }
					fleet_size <= 25
				}
			}
   		}
	}

	on_success = {
		# Teleport fleet to the Champion's Forge system
		fleet = {
			if = {
				limit = {
					is_arkship_fleet = no
					is_mobile = yes
					OR = {
						AND = {
							event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_heavy_late }
							fleet_size <= 500
						}
						AND = {
							event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_medium_late }
							fleet_size <= 200
						}
						AND = {
							event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_medium_mid }
							fleet_size <= 100
						}
						AND = {
							event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_small_mid }
							fleet_size <= 50
						}
						AND = {
							event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_small_early }
							fleet_size <= 25
						}
					}
				}
				save_event_target_as = champions_forge_contestant_fleet
				set_fleet_flag = champions_forge_contestant_fleet
				owner = {
					remove_country_flag = champions_forge_interest
					set_country_flag = champions_forge_contestant_country
					create_champions_forge_contestant = yes
				}
			}
		}
		if = {
			limit = { NOT = { exists = event_target:champions_forge_contestant_fleet } }
			fleet.solar_system.star = {
				random_fleet_in_orbit = {
					limit = {
						is_arkship_fleet = no
						is_mobile = yes
						controller = {
							is_same_value = root.controller
						}
						OR = {
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_heavy_late }
								fleet_size <= 500
							}
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_medium_late }
								fleet_size <= 200
							}
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_medium_mid }
								fleet_size <= 100
							}
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_small_mid }
								fleet_size <= 50
							}
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_small_early }
								fleet_size <= 25
							}
						}
					}
					weights = {
						base = 1
						modifier = {
							add = trigger:fleet_power
						}
					}
					save_event_target_as = champions_forge_contestant_fleet
					set_fleet_flag = champions_forge_contestant_fleet
					owner = {
						remove_country_flag = champions_forge_interest
						set_country_flag = champions_forge_contestant_country
						create_champions_forge_contestant = yes
					}
				}
			}
		}
		if = {
			limit = { NOT = { exists = event_target:champions_forge_contestant_fleet } }
			fleet.solar_system = {
				random_fleet_in_system = {
					limit = {
						is_arkship_fleet = no
						is_mobile = yes
						controller = {
							is_same_value = root.controller
						}
						OR = {
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_heavy_late }
								fleet_size <= 500
							}
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_medium_late }
								fleet_size <= 200
							}
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_medium_mid }
								fleet_size <= 100
							}
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_small_mid }
								fleet_size <= 50
							}
							AND = {
								event_target:champions_forge_enclave_country = { has_country_flag = champions_of_the_forge_weight_class_small_early }
								fleet_size <= 25
							}
						}
					}
					weights = {
						base = 1
						modifier = {
							add = trigger:fleet_power
						}
					}
					save_event_target_as = champions_forge_contestant_fleet
					set_fleet_flag = champions_forge_contestant_fleet
					owner = {
						remove_country_flag = champions_forge_interest
						set_country_flag = champions_forge_contestant_country
						create_champions_forge_contestant = yes
					}
				}
			}
		}
		if = {
			limit = { NOT = { exists = event_target:champions_forge_contestant_fleet } }
			owner = {
				end_event_chain = "champions_forge_tournament_chain"
			}
		}
	}
	on_fail = {
		owner = {
			end_event_chain = "champions_forge_tournament_chain"
		}
	}

	abort_trigger = {
		NOT = {
			has_country_flag = champions_forge_interest
		}
		event_target:champions_forge_enclave_country = { #If the battle has started you don't get to go
			has_country_flag = champions_forge_battle_started
		}
	}
	on_cancel = {
		owner = {
			if = {
				limit = { has_event_chain = champions_forge_tournament_chain }
				end_event_chain = champions_forge_tournament_chain
			}
		}
	}
}

