special_project = { #Spy Satellite
	key = "CONTRACT_ESPIONAGE_SUPPORT_PROJECT_01"
	event_chain = contract_espionage_support_chain
	days_to_research = 30
	project_type = project_type_contract
	picture = GFX_evt_satellite_in_orbit
	icon = "gfx/interface/icons/situation_log/situation_log_quest.dds"
	location = yes
	remove_when_completed = yes

	event_scope = ship_event

	requirements = {
		carries_colony = 1
	}
	on_success = {
		# Contract Event Check
		owner = {
			if = {
				limit = {
					# This shouldn't fire for the Forever Cruise variants
					owner = { has_event_chain = contract_espionage_support_chain }
				}
				country_event = { id = nomads.6000 }
			}
			increase_espionage_counter_effect = yes
			if = {
				limit = {
					NOT = { is_variable_set = espionage_support_counter }
				}
				set_variable = {
					which = espionage_support_counter
					value = 0
				}
			}
